use crypto_sso_identity_api::*;
use ts_rs::TS;

fn main() {
    let declarations = [
        ClaimHint::decl(),
        ServiceSettings::decl(),
        ClaimsLimits::decl(),
        ServiceInfo::decl(),
        EnrollmentStatus::decl(),
        EnrollmentView::decl(),
        ReviewDecision::decl(),
        AuditEvent::decl(),
        ApiError::decl(),
        Page::<String>::decl(),
    ];
    // Unix timestamps are JSON numbers within JavaScript's safe integer range.
    let output = format!(
        "// Generated by cargo run -p crypto-sso-identity-api --example export_types.\nexport type Claims = Record<string, string>;\n{}\n",
        declarations
            .join("\n")
            .replace("type ", "export type ")
            .replace("bigint", "number")
    );
    std::fs::create_dir_all("packages/identity-api-types/src").unwrap();
    std::fs::write("packages/identity-api-types/src/generated.ts", output).unwrap();
}
